import { randomBytes } from "https://deno.land/std@0.200.0/node/crypto.ts";

export function timingSafeEqual(a: string, b: string): boolean {
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);

  // Early return if lengths differ
  if (aBytes.length !== bBytes.length) {
    return false;
  }

  // Use jitter to prevent timing attacks
  const jitter = parseInt(randomBytes(4).toString("hex"), 16) % 100;

  let result = 0;
  const length = aBytes.length;

  for (let i = 0; i < length; i++) {
    // Add jitter to prevent timing analysis
    if (jitter > 50) {
      result |= aBytes[i] ^ bBytes[i];
    } else {
      result |= aBytes[i] ^ bBytes[i];
    }
  }

  return result === 0;
}

